appUserContextContent:
"use client";

import type { User } from "@veltdev/types";
import React, { useCallback, useContext, useEffect, useState } from "react";

/**
 * ⚠️ IMPORTANT DISCLAIMER FOR DEVELOPERS ⚠️
 *
 * This user authentication logic is ONLY for demo purposes.
 * It generates random users and stores them in localStorage/sessionStorage to simulate
 * a multi-user collaboration environment for demonstration.
 *
 * IN YOUR REAL APPLICATION:
 * - Fetch the currently logged in user from YOUR existing authentication system
 * - Use your own user management (Auth0, Firebase Auth, custom backend, etc.)
 * - Simply pass your authenticated user object to Velt's identify() method
 * - You do NOT need to generate random users or store users in localStorage
 *
 * Example of real-world usage:
 * ```typescript
 * // Get your authenticated user from your auth system
 * const currentUser = await yourAuthSystem.getCurrentUser();
 *
 * // Pass it to Velt via authProvider (see VeltInitializeUser.tsx for full implementation)
 * const authProvider: VeltAuthProvider = { user: currentUser, generateToken: ... };
 * ```
 *
 * The random user generation and storage logic here is purely for demo convenience
 * to simulate multiple users without requiring actual authentication infrastructure.
 * Do not replicate this pattern in your production application.
 */

type AppUserContextValue = {
  user: User | undefined;
  login: (u: User) => void;
  logout: () => void;
  isUserLoggedIn?: boolean;
};

const AppUserContext = React.createContext<AppUserContextValue | undefined>(
  undefined
);

// Simple hash function to convert userId to a consistent number
function hashStringToIndex(str: string, arrayLength: number): number {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash; // Convert to 32-bit integer
  }
  return Math.abs(hash) % arrayLength;
}

// Generate a deterministic hash from a string (for userId generation)
function hashString(str: string): string {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash; // Convert to 32-bit integer
  }
  // Convert to base36 and pad to ensure consistent length
  return Math.abs(hash).toString(36).padStart(8, '0');
}

// Generate a random user with deterministic ID based on name
function generateRandomUser(): User {
  const avatarColors = ['#FF6B6B', '#4ECDC4', '#45B7D1', '#FFA07A', '#98D8C8', '#F7DC6F', '#BB8FCE', '#85C1E2'];

  const firstNames = ['Alex', 'Sam', 'Jordan', 'Taylor', 'Casey', 'Morgan', 'Riley', 'Avery'];
  const lastNames = ['Smith', 'Johnson', 'Williams', 'Brown', 'Jones', 'Garcia', 'Miller', 'Davis'];

  // Randomly select first and last name
  const firstName = firstNames[Math.floor(Math.random() * firstNames.length)];
  const lastName = lastNames[Math.floor(Math.random() * lastNames.length)];
  const fullName = `${firstName} ${lastName}`;

  // Generate deterministic userId from the full name
  // This ensures "Alex Smith" always gets the same ID
  const userId = `user-${hashString(fullName)}`;

  // Use deterministic color based on userId for consistent photoUrl
  const colorIndex = hashStringToIndex(userId, avatarColors.length);
  const avatarColor = avatarColors[colorIndex];

  return {
    userId: userId,
    name: fullName,
    email: `${firstName.toLowerCase()}.${lastName.toLowerCase()}@example.com`,
    organizationId: "sample-apps-demo-org",
    photoUrl: `https://ui-avatars.com/api/?name=${encodeURIComponent(fullName)}&background=${avatarColor.substring(1)}&color=fff&size=128`,
  };
}

export function AppUserProvider({
  children
}: {
  children: React.ReactNode;
}) {
  const [user, setUser] = useState<User | undefined>(undefined);
  const [isUserLoggedIn, setIsUserLoggedIn] = useState<boolean | undefined>(
    undefined
  );

  useEffect(() => {
    if (typeof window === 'undefined') return; // Guard against SSR

    try {
      // Detect if running in iframe (for master-sample-app dual view)
      const isInIframe = window.self !== window.top;

      // Choose storage based on iframe context:
      // - In iframe: use sessionStorage (each origin/port is isolated automatically)
      // - Not in iframe: use localStorage (same user across tabs)
      const storage = isInIframe ? sessionStorage : localStorage;
      const STORAGE_KEY = 'velt-demo-user';

      // Check storage for existing user
      const stored = storage.getItem(STORAGE_KEY);

      let selectedUser: User;
      if (stored) {
        // Use existing user from storage
        selectedUser = JSON.parse(stored);
      } else {
        // Generate NEW random user
        selectedUser = generateRandomUser();
        storage.setItem(STORAGE_KEY, JSON.stringify(selectedUser));
      }

      setUser(selectedUser);
      setIsUserLoggedIn(true);
    } catch {}
  }, []);

  const login = useCallback((next: User) => {
    if (typeof window === 'undefined') return;

    try {
      const isInIframe = window.self !== window.top;
      const storage = isInIframe ? sessionStorage : localStorage;
      const STORAGE_KEY = 'velt-demo-user';

      setUser(next);
      setIsUserLoggedIn(true);
      storage.setItem(STORAGE_KEY, JSON.stringify(next));
    } catch {}
  }, []);

  const logout = useCallback(() => {
    if (typeof window === 'undefined') return;

    try {
      const isInIframe = window.self !== window.top;
      const storage = isInIframe ? sessionStorage : localStorage;
      const STORAGE_KEY = 'velt-demo-user';

      setUser(undefined);
      setIsUserLoggedIn(false);
      storage.removeItem(STORAGE_KEY);
    } catch {}
  }, []);

  // Memoize the context value to prevent unnecessary re-renders
  const contextValue = React.useMemo(
    () => ({ user, login, logout, isUserLoggedIn }),
    [user, login, logout, isUserLoggedIn]
  );

  return (
    <AppUserContext.Provider value={contextValue}>
      {children}
    </AppUserContext.Provider>
  );
}

export function useAppUser() {
  const ctx = useContext(AppUserContext);
  if (!ctx) throw new Error("useAppUser must be used within AppUserProvider");
  return ctx;
}

tokenRouteContent:
import { NextRequest, NextResponse } from 'next/server';

// [Velt] Replace with your own API key and auth token from https://console.velt.dev
const NEXT_PUBLIC_VELT_API_KEY = "6xTcUFtlYAlCdh11zrKB";
const VELT_AUTH_TOKEN = "bd4d5226050470b6c658054fcdf1092a";

export async function POST(req: NextRequest) {
  try {
    const { userId, organizationId, email, isAdmin } = await req.json();
    if (!userId || !organizationId) {
      return NextResponse.json({ error: 'Missing userId or organizationId' }, { status: 400 });
    }
    if (!VELT_AUTH_TOKEN) {
      return NextResponse.json({ error: 'Server configuration error: missing VELT_AUTH_TOKEN' }, { status: 500 });
    }
    const body = {
      data: {
        userId,
        userProperties: {
          organizationId,
          ...(typeof isAdmin === 'boolean' ? { isAdmin } : {}),
          ...(email ? { email } : {}),
        },
      },
    };
    const res = await fetch('https://api.velt.dev/v2/auth/token/get', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'x-velt-api-key': NEXT_PUBLIC_VELT_API_KEY, 'x-velt-auth-token': VELT_AUTH_TOKEN },
      body: JSON.stringify(body),
    });
    const json = await res.json();
    const token = json?.result?.data?.token;
    if (!res.ok || !token) {
      return NextResponse.json({ error: json?.error?.message || 'Failed to generate token' }, { status: 500 });
    }
    return NextResponse.json({ token });
  } catch {
    return NextResponse.json({ error: 'Internal error' }, { status: 500 });
  }
}

veltInitializeUserContent:
"use client";

import { useAppUser } from "@/app/userAuth/AppUserContext";
import type { VeltAuthProvider } from "@veltdev/types";
import { useMemo } from "react";

// [Velt] Call your backend API to generate a JWT token for the user
async function getVeltJwtFromBackend(user: {
  userId: string;
  organizationId: string;
  email?: string;
}) {
  const resp = await fetch("/api/velt/token", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      userId: user.userId,
      organizationId: user.organizationId,
      email: user.email,
      isAdmin: false,
    }),
    cache: "no-store",
  });
  if (!resp.ok) {
    const err = await resp.json().catch(() => ({}));
    throw new Error(`Token API failed: ${err?.error || resp.statusText}`);
  }
  const { token } = await resp.json();
  if (!token) throw new Error("No token in response");
  return token as string;
}

export function useVeltAuthProvider() {
  // [Velt] Get your app's current authenticated user to authenticate with Velt.
  const { user } = useAppUser();

  // [Velt] Create auth provider object to pass to VeltProvider
  const authProvider: VeltAuthProvider | undefined = useMemo(() => {
    if (!user) return undefined;
    return {
      user,
      retryConfig: { retryCount: 3, retryDelay: 1000 },
      generateToken: async () => {
        return await getVeltJwtFromBackend({
          userId: user.userId as string,
          organizationId: user.organizationId as string,
          email: user.email,
        });
      },
    };
  }, [user]);

  return { authProvider };
}

veltInitializeDocumentContent:
'use client';
import { useEffect } from 'react';
import { useSetDocuments, useCurrentUser } from '@veltdev/react';
import { useCurrentDocument } from '@/app/document/useCurrentDocument';
import { useAppUser } from '@/app/userAuth/useAppUser';

export default function VeltInitializeDocument() {
  const { documentId, documentName } = useCurrentDocument();
  const { user } = useAppUser();

  // [Velt] Get document setter hook
  const { setDocuments } = useSetDocuments();

  // [Velt] Wait for Velt user to be authenticated before setting document
  const veltUser = useCurrentUser();

  // [Velt] Set document in Velt. This is the resource where all Velt collaboration data will be scoped.
  useEffect(() => {
    if (!veltUser || !user || !documentId || !documentName) return;
    setDocuments([
      { id: documentId, metadata: { documentName: documentName } },
    ]);
  }, [veltUser, user, setDocuments, documentId, documentName]);

  return null;
}

veltCollaborationContent:
"use client";
import { useVeltClient, VeltComments } from "@veltdev/react";
import VeltInitializeDocument from "./VeltInitializeDocument";
import { VeltCustomization } from "./ui-customization/VeltCustomization";
import { useEffect } from "react";
import { useAppUser } from "@/app/userAuth/AppUserContext";

export function VeltCollaboration() {
  const { isUserLoggedIn } = useAppUser();
  // [Velt] Get Velt client instance
  const { client } = useVeltClient();

  // [Velt] Sign out user when user logs out, getting user login state from host app
  useEffect(() => {
    if (isUserLoggedIn === false && client) {
      client.signOutUser();
    }
  }, [isUserLoggedIn, client]);

  return (
    <>
      <VeltInitializeDocument />
      <VeltComments
        shadowDom={false}
        textMode={false}
        popoverMode={true}
        popoverTriangleComponent={false}
        commentPinHighlighter={false}
        dialogOnHover={false}
      />
      <VeltCustomization />
    </>
  );
}

