mapStoreEditorContent:
'use client'

import { useState, useRef, useCallback, useMemo } from 'react'
import { useStore } from '@veltdev/crdt-react'
import { useVeltClient, useLiveState, VeltCommentsSidebar, useGetCommentAnnotations } from '@veltdev/react'
import { FocusMap } from './types'
import { STORE_ID, CURSOR_COLORS, initialMapData, storeItems } from './constants'
import { PlusIcon } from './icons'
import MapEntryRow from './MapEntryRow'
import MapStoreSidebar from './MapStoreSidebar'
import MapCommentsModal from './MapCommentsModal'
import { useAppUser } from '@/app/userAuth/useAppUser'
import { useVeltEventHandlers } from '@/components/velt/useVeltEventHandlers'

function hashToIndex(str: string, len: number): number {
  let hash = 0
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) - hash) + str.charCodeAt(i)
    hash = hash & hash
  }
  return Math.abs(hash) % len
}

export default function MapStoreEditor() {
  const { client } = useVeltClient()
  const { user } = useAppUser()

  // CRDT map store
  const {
    value: entries,
    update: updateEntries,
    store,
    status,
    isSynced,
  } = useStore<Record<string, string>>({
    storeId: STORE_ID,
    type: 'map',
    initialValue: initialMapData,
  })

  // Local UI state
  const [selectedStoreId, setSelectedStoreId] = useState('image-store')
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false)

  // Drag-and-drop state
  const [dragIndex, setDragIndex] = useState<number | null>(null)
  const [dragOverIndex, setDragOverIndex] = useState<number | null>(null)

  // Synced key order via useLiveState so reordering is shared
  const [keyOrder, setKeyOrder] = useLiveState<string[]>('core-crdt-map-key-order', [], {
    syncDuration: 100,
  })

  // Comment sidebar state
  const [isGlobalSidebarOpen, setIsGlobalSidebarOpen] = useState(false)
  const [activeCommentToolId, setActiveCommentToolId] = useState<string | null>(null)

  // Comment modal state
  const [isCommentModalOpen, setIsCommentModalOpen] = useState(false)
  const [selectedCommentKey, setSelectedCommentKey] = useState<string | null>(null)
  const [selectedCommentValue, setSelectedCommentValue] = useState<string | null>(null)

  // Annotation data for comment counts
  const commentAnnotations = useGetCommentAnnotations()

  const annotationDataByTargetId = useMemo(() => {
    const dataMap: Record<string, { count: number; hasUnread: boolean }> = {}
    if (commentAnnotations?.data) {
      Object.values(commentAnnotations.data).forEach((annotations: any[]) => {
        annotations.forEach((annotation) => {
          const targetId = annotation.targetElementId
          if (targetId) {
            if (!dataMap[targetId]) {
              dataMap[targetId] = { count: 0, hasUnread: false }
            }
            if (annotation.status?.id !== 'RESOLVED') {
              dataMap[targetId].count = annotation.comments?.length || 0
            }
            if (annotation.unread) {
              dataMap[targetId].hasUnread = true
            }
          }
        })
      })
    }
    return dataMap
  }, [commentAnnotations])

  const handleCommentClick = useCallback((key: string, value: string) => {
    setSelectedCommentKey(key)
    setSelectedCommentValue(value)
    setIsCommentModalOpen(true)
  }, [])

  const toggleGlobalSidebar = useCallback(() => {
    setIsGlobalSidebarOpen(prev => !prev)
  }, [])

  const openGlobalSidebar = useCallback(() => {
    setIsGlobalSidebarOpen(true)
  }, [])

  useVeltEventHandlers({
    toggleGlobalSidebar,
    openGlobalSidebar,
    setActiveCommentToolId,
  })

  // Get local user info
  const localUserRef = useRef<{ userId: string; name: string; color: string } | null>(null)
  if (!localUserRef.current && client) {
    try {
      const u = (client as any).getUser?.()
      if (u) {
        localUserRef.current = {
          userId: u.userId || 'anonymous',
          name: u.name || 'Anonymous',
          color: CURSOR_COLORS[hashToIndex(u.userId || u.name || '', CURSOR_COLORS.length)],
        }
      }
    } catch { /* ignore */ }
  }

  // Live focus broadcasting
  const [focuses, setFocuses] = useLiveState<FocusMap>('core-crdt-map-focuses', {}, {
    syncDuration: 100,
    listenToNewChangesOnly: true,
  })
  const focusesRef = useRef<FocusMap>(focuses || {})
  focusesRef.current = focuses || {}

  const broadcastFocus = useCallback((entryKey: string | null) => {
    if (!localUserRef.current) return
    const u = localUserRef.current
    setFocuses({
      ...focusesRef.current,
      [u.userId]: {
        name: u.name,
        color: u.color,
        entryKey,
        timestamp: Date.now(),
      },
    })
  }, [setFocuses])

  // Remote focus map
  const remoteFocusMap = useMemo(() => {
    const map: Record<string, { name: string; color: string }> = {}
    for (const [uid, entry] of Object.entries(focuses || {})) {
      if (uid === localUserRef.current?.userId) continue
      if (Date.now() - entry.timestamp > 30000) continue
      if (entry.entryKey) {
        map[entry.entryKey] = { name: entry.name, color: entry.color }
      }
    }
    return map
  }, [focuses])

  // Status indicator
  const statusDotColor =
    status === 'connected' ? (isSynced ? '#22c55e' : '#eab308') :
    status === 'connecting' ? '#eab308' : '#ef4444'
  const statusLabel =
    status === 'connected' ? (isSynced ? 'Synced' : 'Syncing...') :
    status === 'connecting' ? 'Connecting...' : 'Disconnected'

  // Get entries as ordered [key, value] pairs
  const entriesObj = (entries && typeof entries === 'object' && !Array.isArray(entries)) ? entries : {}
  const allKeys = Object.keys(entriesObj)

  // Build ordered key list: use synced keyOrder, then append any new keys not yet in the order
  const currentOrder = Array.isArray(keyOrder) ? keyOrder : []
  const orderedKeys = useMemo(() => {
    const validOrdered = currentOrder.filter(k => allKeys.includes(k))
    const newKeys = allKeys.filter(k => !currentOrder.includes(k))
    return [...validOrdered, ...newKeys]
  }, [currentOrder, allKeys])

  const entryPairs = orderedKeys.map(k => [k, entriesObj[k] ?? ''] as [string, string])

  // CRDT mutation handlers
  const addEntry = useCallback(() => {
    const current = store?.getValue() || {}
    const obj = (current && typeof current === 'object' && !Array.isArray(current)) ? current : {}
    let newKey = 'New Key'
    let counter = 1
    while (obj[newKey] !== undefined) {
      newKey = `New Key ${counter++}`
    }
    updateEntries({ ...obj, [newKey]: '' })
    setKeyOrder([...orderedKeys, newKey])
  }, [store, updateEntries, orderedKeys, setKeyOrder])

  const updateEntry = useCallback((oldKey: string, newKey: string, newValue: string) => {
    const current = store?.getValue() || {}
    const obj = (current && typeof current === 'object' && !Array.isArray(current)) ? current : {}
    const updated = { ...obj }
    if (oldKey !== newKey) {
      delete updated[oldKey]
    }
    updated[newKey] = newValue
    updateEntries(updated)
    if (oldKey !== newKey) {
      setKeyOrder(orderedKeys.map(k => k === oldKey ? newKey : k))
    }
  }, [store, updateEntries, orderedKeys, setKeyOrder])

  const deleteEntry = useCallback((key: string) => {
    const current = store?.getValue() || {}
    const obj = (current && typeof current === 'object' && !Array.isArray(current)) ? current : {}
    const updated = { ...obj }
    delete updated[key]
    updateEntries(updated)
    setKeyOrder(orderedKeys.filter(k => k !== key))
  }, [store, updateEntries, orderedKeys, setKeyOrder])

  // Drag handlers
  const handleDragStart = useCallback((index: number) => {
    setDragIndex(index)
  }, [])

  const handleDragOver = useCallback((e: React.DragEvent, index: number) => {
    e.preventDefault()
    setDragOverIndex(index)
  }, [])

  const handleDragEnd = useCallback(() => {
    if (dragIndex !== null && dragOverIndex !== null && dragIndex !== dragOverIndex) {
      const newOrder = [...orderedKeys]
      const [moved] = newOrder.splice(dragIndex, 1)
      newOrder.splice(dragOverIndex, 0, moved)
      setKeyOrder(newOrder)
    }
    setDragIndex(null)
    setDragOverIndex(null)
  }, [dragIndex, dragOverIndex, orderedKeys, setKeyOrder])

  // Selected store name
  const selectedStore = storeItems.find(s => s.id === selectedStoreId)
  const storeName = selectedStore?.name || 'Image Store'

  return (
    <div className="flex h-screen" style={{ fontFamily: 'Inter, sans-serif' }}>
      {/* Sidebar */}
      <MapStoreSidebar
        selectedStoreId={selectedStoreId}
        onSelectStore={setSelectedStoreId}
        userName={user?.name || 'S'}
        isCollapsed={sidebarCollapsed}
        onToggleCollapse={() => setSidebarCollapsed(prev => !prev)}
      />

      {/* Main content + comment sidebar */}
      <div className="flex flex-1 overflow-hidden" style={{ backgroundColor: 'var(--task-bg)' }}>
        <div className="flex-1 overflow-y-auto">
          <div className="max-w-[600px] mx-auto px-10 pt-10">
            {/* Status */}
            <div className="flex items-center gap-1.5 mb-6">
              <span className="inline-block w-2 h-2 rounded-full shrink-0" style={{ backgroundColor: statusDotColor }} />
              <span className="text-xs" style={{ color: 'var(--app-text-tertiary)' }}>{statusLabel}</span>
            </div>

            {/* Title section */}
            <div className="flex flex-col gap-3 mb-7">
              <h1
                className="text-[32px] font-bold leading-tight"
                style={{ fontFamily: 'Inter, sans-serif', color: 'var(--task-text)' }}
              >
                {storeName}
              </h1>
              <p
                className="text-base"
                style={{ fontFamily: 'Inter, sans-serif', color: 'var(--task-text)' }}
              >
                Store image name and urls
              </p>
            </div>

            {/* Entry rows */}
            <div className="flex flex-col gap-3 pb-6">
              {entryPairs.map(([key, value], index) => {
                const remoteFocus = remoteFocusMap[key]
                const targetId = `map-entry-${key.replace(/\s+/g, '-').toLowerCase()}`
                return (
                  <MapEntryRow
                    key={key}
                    entryKey={key}
                    entryValue={value as string}
                    index={index}
                    remoteFocusUser={remoteFocus?.name || null}
                    remoteFocusColor={remoteFocus?.color || null}
                    annotationData={annotationDataByTargetId[targetId]}
                    onUpdate={updateEntry}
                    onDelete={deleteEntry}
                    onFocus={broadcastFocus}
                    onCommentClick={handleCommentClick}
                    onDragStart={handleDragStart}
                    onDragOver={handleDragOver}
                    onDragEnd={handleDragEnd}
                    isDragOver={dragOverIndex === index}
                  />
                )
              })}
            </div>

            {/* Add button */}
            <button
              className="flex items-center justify-center rounded-full hover:bg-blue-50 transition-colors"
              style={{
                width: 32,
                height: 32,
                border: '1px solid rgb(0,109,220)',
              }}
              onClick={addEntry}
            >
              <PlusIcon size={16} color="rgb(0,109,220)" />
            </button>

            {entryPairs.length === 0 && (
              <div className="text-center py-12 text-sm" style={{ color: 'var(--task-text-secondary)' }}>
                No entries yet. Click the + button to add a key-value pair.
              </div>
            )}
          </div>
        </div>

        {/* Comment sidebar */}
        {isGlobalSidebarOpen && (
          <div className="velt-sidebar-container h-full flex-shrink-0">
            <VeltCommentsSidebar
              shadowDom={false}
              pageMode={true}
              embedMode={true}
              focusedThreadMode={true}
              sortOrder="asc"
              sortBy="createdAt"
            />
          </div>
        )}
      </div>

      {/* Comment modal */}
      <MapCommentsModal
        isOpen={isCommentModalOpen}
        selectedEntryKey={selectedCommentKey}
        selectedEntryValue={selectedCommentValue}
        onClose={() => {
          setIsCommentModalOpen(false)
          setSelectedCommentKey(null)
          setSelectedCommentValue(null)
        }}
      />
    </div>
  )
}

mapEntryRowContent:
'use client'

import { useState, useRef, useEffect } from 'react'
import { GripVerticalIcon, TrashIcon, CommentIcon } from './icons'

interface MapEntryRowProps {
  entryKey: string
  entryValue: string
  index: number
  remoteFocusUser: string | null
  remoteFocusColor: string | null
  annotationData: { count: number; hasUnread: boolean } | undefined
  onUpdate: (oldKey: string, newKey: string, newValue: string) => void
  onDelete: (key: string) => void
  onFocus: (key: string) => void
  onCommentClick: (key: string, value: string) => void
  onDragStart: (index: number) => void
  onDragOver: (e: React.DragEvent, index: number) => void
  onDragEnd: () => void
  isDragOver: boolean
}

export default function MapEntryRow({
  entryKey,
  entryValue,
  index,
  remoteFocusUser,
  remoteFocusColor,
  annotationData,
  onUpdate,
  onDelete,
  onFocus,
  onCommentClick,
  onDragStart,
  onDragOver,
  onDragEnd,
  isDragOver,
}: MapEntryRowProps) {
  const [editKey, setEditKey] = useState(entryKey)
  const [editValue, setEditValue] = useState(entryValue)
  const keyRef = useRef<HTMLInputElement>(null)
  const valueRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    setEditKey(entryKey)
  }, [entryKey])

  useEffect(() => {
    setEditValue(entryValue)
  }, [entryValue])

  const handleKeyBlur = () => {
    if (editKey.trim() && editKey !== entryKey) {
      onUpdate(entryKey, editKey.trim(), editValue)
    } else if (!editKey.trim()) {
      setEditKey(entryKey)
    }
  }

  const handleValueBlur = () => {
    if (editValue !== entryValue) {
      onUpdate(entryKey, editKey, editValue)
    }
  }

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      ;(e.target as HTMLInputElement).blur()
    } else if (e.key === 'Escape') {
      setEditKey(entryKey)
      setEditValue(entryValue)
      ;(e.target as HTMLInputElement).blur()
    }
  }

  const targetElementId = `map-entry-${entryKey.replace(/\s+/g, '-').toLowerCase()}`

  return (
    <div
      className="flex items-center gap-[10px] transition-transform"
      style={{
        borderTop: isDragOver ? '2px solid rgb(1,108,221)' : '2px solid transparent',
      }}
      onDragOver={(e) => onDragOver(e, index)}
    >
      {/* Grip handle */}
      <div
        className="w-8 h-8 flex items-center justify-center shrink-0 cursor-grab active:cursor-grabbing"
        draggable
        onDragStart={() => onDragStart(index)}
        onDragEnd={onDragEnd}
      >
        <GripVerticalIcon size={16} color="var(--task-text)" />
      </div>

      {/* Card */}
      <div
        id={targetElementId}
        className="map-entry-row flex-1 flex items-center gap-5 relative group"
        style={{
          borderLeft: remoteFocusColor ? `3px solid ${remoteFocusColor}` : undefined,
        }}
        onClick={() => onFocus(entryKey)}
      >
        {/* Remote focus label */}
        {remoteFocusUser && (
          <div
            className="absolute -top-2 -left-1 text-[10px] font-semibold px-1.5 py-0.5 rounded text-white z-10"
            style={{ backgroundColor: remoteFocusColor || '#999' }}
          >
            {remoteFocusUser}
          </div>
        )}

        {/* Key input */}
        <input
          ref={keyRef}
          className="bg-transparent border-none outline-none text-base font-medium flex-1 min-w-0"
          style={{ fontFamily: 'Inter, sans-serif', color: 'var(--task-text)' }}
          value={editKey}
          onChange={(e) => setEditKey(e.target.value)}
          onBlur={handleKeyBlur}
          onKeyDown={handleKeyDown}
          onFocus={() => onFocus(entryKey)}
        />

        {/* Vertical separator */}
        <div
          className="w-0 h-5 shrink-0"
          style={{ borderLeft: '1px solid var(--task-separator)' }}
        />

        {/* Value input */}
        <input
          ref={valueRef}
          className="bg-transparent border-none outline-none text-base font-medium flex-1 min-w-0"
          style={{ fontFamily: 'Inter, sans-serif', color: 'var(--task-text)' }}
          value={editValue}
          onChange={(e) => setEditValue(e.target.value)}
          onBlur={handleValueBlur}
          onKeyDown={handleKeyDown}
          onFocus={() => onFocus(entryKey)}
        />

        {/* Actions */}
        <div className="flex items-center gap-1 shrink-0 w-[72px] justify-end" onClick={(e) => e.stopPropagation()}>
          <button
            className="flex items-center justify-center p-1.5 hover:bg-black/5 dark:hover:bg-white/5 rounded transition-colors"
            onClick={() => onCommentClick(entryKey, entryValue)}
            title="Comments"
          >
            <CommentIcon
              count={annotationData?.count || 0}
              hasUnread={annotationData?.hasUnread || false}
            />
          </button>
          <button
            className="flex items-center justify-center p-1.5 hover:bg-red-50 dark:hover:bg-red-900/20 rounded transition-opacity opacity-0 group-hover:opacity-100"
            onClick={(e) => {
              e.stopPropagation()
              onDelete(entryKey)
            }}
            title="Delete entry"
          >
            <TrashIcon size={18} color="var(--task-text)" />
          </button>
        </div>
      </div>
    </div>
  )
}

mapStoreSidebarContent:
'use client'

import { useState } from 'react'
import { storeItems, storeSections } from './constants'
import { SearchIcon, ColumnsIcon, CollapseIcon } from './icons'

interface MapStoreSidebarProps {
  selectedStoreId: string
  onSelectStore: (storeId: string) => void
  userName: string
  isCollapsed: boolean
  onToggleCollapse: () => void
}

export default function MapStoreSidebar({
  selectedStoreId,
  onSelectStore,
  userName,
  isCollapsed,
  onToggleCollapse,
}: MapStoreSidebarProps) {
  const [searchQuery, setSearchQuery] = useState('')

  const userInitial = userName.charAt(0).toUpperCase()

  if (isCollapsed) {
    return (
      <div className="h-full flex flex-col items-center py-3" style={{ width: 48, backgroundColor: 'var(--task-sidebar-bg)' }}>
        <button
          onClick={onToggleCollapse}
          className="w-10 h-10 flex items-center justify-center rounded-lg hover:bg-gray-100 transition-colors"
          style={{ transform: 'rotate(180deg)' }}
        >
          <CollapseIcon size={16} color="var(--task-text)" />
        </button>
      </div>
    )
  }

  const filteredSections = storeSections.map(section => ({
    ...section,
    items: section.items.filter(itemId => {
      const item = storeItems.find(s => s.id === itemId)
      return item?.name.toLowerCase().includes(searchQuery.toLowerCase())
    }),
  })).filter(section => section.items.length > 0)

  return (
    <div
      className="h-full flex flex-col justify-between shrink-0"
      style={{ width: 251, backgroundColor: 'var(--task-sidebar-bg)' }}
    >
      <div className="flex flex-col gap-2 p-3">
        {/* Search */}
        <div
          className="flex items-center gap-2 px-2 h-8 rounded-lg"
          style={{ border: '1px solid var(--task-border)' }}
        >
          <SearchIcon size={16} color="var(--task-text)" />
          <input
            className="flex-1 bg-transparent border-none outline-none text-xs"
            style={{ fontFamily: 'Inter, sans-serif', color: 'var(--task-text)' }}
            placeholder="Search Lists"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>

        {/* Store sections */}
        {filteredSections.map(section => (
          <div key={section.header} className="flex flex-col gap-0.5">
            <div
              className="px-2 py-2 text-xs rounded-lg"
              style={{ fontFamily: 'Inter, sans-serif', color: 'var(--task-text)' }}
            >
              {section.header}
            </div>
            {section.items.map(itemId => {
              const item = storeItems.find(s => s.id === itemId)!
              const isSelected = itemId === selectedStoreId
              return (
                <button
                  key={itemId}
                  className="flex items-center gap-2 px-2 h-8 rounded-lg text-left transition-colors"
                  style={{
                    backgroundColor: isSelected ? 'rgb(1,108,221)' : 'transparent',
                  }}
                  onClick={() => onSelectStore(itemId)}
                >
                  <ColumnsIcon size={16} color={isSelected ? 'rgb(254,255,255)' : 'var(--task-text)'} />
                  <span
                    className="text-xs"
                    style={{
                      fontFamily: 'Inter, sans-serif',
                      color: isSelected ? 'rgb(254,255,255)' : 'var(--task-text)',
                    }}
                  >
                    {item.name}
                  </span>
                </button>
              )
            })}
          </div>
        ))}
      </div>

      {/* Bottom bar */}
      <div className="flex items-center justify-between px-4 py-3" style={{ height: 48 }}>
        <div className="flex items-center gap-2">
          <div
            className="flex items-center justify-center rounded"
            style={{ width: 16, height: 16, backgroundColor: 'rgb(245,93,103)' }}
          >
            <span
              className="text-center font-bold"
              style={{ fontFamily: 'Urbanist, sans-serif', fontSize: 11, color: 'var(--task-text)' }}
            >
              {userInitial}
            </span>
          </div>
          <span style={{ fontFamily: 'Urbanist, sans-serif', fontSize: 14, color: 'var(--task-text)' }}>
            Todo
          </span>
        </div>
        <button
          className="w-6 h-6 flex items-center justify-center rounded hover:bg-gray-100 transition-colors"
          onClick={onToggleCollapse}
        >
          <CollapseIcon size={16} color="var(--task-text)" />
        </button>
      </div>
    </div>
  )
}

